COMANDO_VETO = 'python "${CLAUDE_PROJECT_DIR}/.claude/hooks/vetar-branch-protegida.py"'
COMANDO_VETO_CREDENCIAL = 'python "${CLAUDE_PROJECT_DIR}/.claude/hooks/vetar-credencial.py"'
COMANDO_CONFERIR_MCP = 'python "${CLAUDE_PROJECT_DIR}/.claude/hooks/conferir-mcp.py"'

def comandos_de(bloco: dict) -> list:
    """Os comandos declarados num bloco de gancho do settings.json."""
    ganchos = bloco.get("hooks", []) if isinstance(bloco, dict) else []
    return [g.get("command", "") for g in ganchos if isinstance(g, dict)]


def tem_comando(lista: list, comando: str) -> bool:
    return any(comando in comandos_de(b) for b in lista)


def tirar_outras_formas(lista: list, arquivo: str, comando_novo: str) -> bool:
    """Remove declarações do mesmo gancho que não sejam a forma canônica.

    Pega a relativa que a camada gerava antes — quebra quando o cwd anda — e
    a absoluta que alguém fixou à mão numa máquina: caminho absoluto é
    resíduo de máquina num arquivo que entra no git, e a duplicata rodaria o
    gancho duas vezes. Compara o comando de verdade, nunca o JSON
    serializado: as aspas do comando novo viram \\" no texto e a busca por
    substring casa errado. True se removeu algo.
    """
    filtrada = [b for b in lista
                if not any(arquivo in c and c != comando_novo
                           for c in comandos_de(b))]
    mudou = len(filtrada) != len(lista)
    lista[:] = filtrada
    return mudou

MARCA_INICIO = "# === PÁGINAS (gerado — não edite à mão) ==="
MARCA_FIM = "# === FIM DAS PÁGINAS ==="
MARCA_MODULOS = "# === MÓDULOS (gerado — não edite à mão) ==="
MARCA_MODULOS_FIM = "# === FIM DOS MÓDULOS ==="


def paginas_no_disco(raiz: Path) -> dict:
    """Lê do disco os arquivos que devem estar embutidos.

    Página é texto; skill pode trazer asset binário (uma imagem, por exemplo).
    O que não decodifica como texto viaja como bytes — o padrão Agent Skills
    permite assets, e recusá-los deixaria a skill para trás.
    """
    achados = {}
    for padrao in FONTES:
        for caminho in sorted(raiz.glob(padrao)):
            if not caminho.is_file() or caminho.name == ".gitkeep":
                continue
            rotulo = caminho.relative_to(raiz).as_posix()
            try:
                achados[rotulo] = caminho.read_text(encoding="utf-8")
            except UnicodeDecodeError:
                achados[rotulo] = caminho.read_bytes()
    return achados


def modulos_no_disco(raiz: Path) -> dict:
    """Lê modulos/<nome>/ e devolve {nome: {caminho de destino: conteúdo}}.

    O caminho relativo dentro da pasta do módulo é o caminho de destino, tal e
    qual. Mesmo tratamento das páginas para o conteúdo: o que não decodifica
    como texto viaja como bytes, porque skill pode trazer asset binário.
    """
    achados = {}
    origem = raiz / PASTA_MODULOS
    if not origem.is_dir():
        return achados
    for pasta in sorted(p for p in origem.iterdir() if p.is_dir()):
        arquivos = {}
        for caminho in sorted(pasta.rglob("*")):
            if not caminho.is_file() or caminho.name == ".gitkeep":
                continue
            rotulo = caminho.relative_to(pasta).as_posix()
            if rotulo == CARTAO_MODULO:
                continue
            try:
                arquivos[rotulo] = caminho.read_text(encoding="utf-8")
            except UnicodeDecodeError:
                arquivos[rotulo] = caminho.read_bytes()
        if arquivos:
            achados[pasta.name] = arquivos
    return achados


def trocar_bloco(linhas: list, inicio: str, fim: str, corpo: list) -> tuple:
    """Troca o miolo entre duas marcas. Devolve (linhas novas, mudou?).

    As posições são recalculadas a cada chamada de propósito: trocar um bloco
    move as linhas do outro, e índice guardado de antes apontaria para o lugar
    errado — do jeito mais silencioso possível, no meio de um dicionário.
    """
    try:
        i = next(n for n, l in enumerate(linhas) if l.startswith(inicio))
        f = next(n for n, l in enumerate(linhas) if l.startswith(fim))
    except StopIteration:
        sys.exit(f"Marca não encontrada neste arquivo: {inicio}")
    return linhas[:i] + corpo + linhas[f:], "".join(corpo) != "".join(linhas[i:f])


def bloco_de(marca: str, nome: str, itens: dict) -> list:
    """As linhas de um dicionário embutido, com a marca de abertura na frente."""
    return ([f"{marca}\n", f"{nome} = {{\n"]
            + [f"    {chave!r}: {valor!r},\n" for chave, valor in itens.items()]
            + ["}\n"])


def sincronizar(raiz: Path) -> int:
    """Reescreve as seções geradas deste arquivo a partir dos arquivos reais."""
    eu = Path(__file__)
    linhas = eu.read_text(encoding="utf-8").splitlines(keepends=True)

    achadas = paginas_no_disco(raiz)
    if not achadas:
        sys.exit("Nenhuma página encontrada. Rode na raiz do repositório da camada.")
    modulos = modulos_no_disco(raiz)

    linhas, mudou_paginas = trocar_bloco(
        linhas, MARCA_INICIO, MARCA_FIM, bloco_de(MARCA_INICIO, "PAGINAS", achadas))
    linhas, mudou_modulos = trocar_bloco(
        linhas, MARCA_MODULOS, MARCA_MODULOS_FIM,
        bloco_de(MARCA_MODULOS, "MODULOS", modulos))

    # O número de versão sobe sozinho, mas só quando o conteúdo mudou de
    # verdade — sincronizar sem mudança não fabrica versão nova.
    versao = VERSAO
    if mudou_paginas or mudou_modulos:
        maior, menor = VERSAO.split(".")
        versao = f"{maior}.{int(menor) + 1}"
        for n, l in enumerate(linhas):
            if l.startswith("VERSAO = "):
                linhas[n] = f'VERSAO = "{versao}"\n'
                break

    eu.write_text("".join(linhas), encoding="utf-8", newline="\n")
    for rotulo in achadas:
        print(f"  embutida: {rotulo}")
    print(f"\n{len(achadas)} páginas sincronizadas — camada {versao}.")

    if modulos:
        print(f"\nMódulos de {PASTA_MODULOS}/ — embutidos, mas nenhum viaja sozinho:")
        for nome, arquivos in modulos.items():
            print(f"  embutido: {nome} — {len(arquivos)} arquivos")

    # Editar skill também passa por aqui — sem o espelho junto, o Claude Code
    # seguiria lendo a versão velha em .claude/skills até alguém rodar o montar.
    print(f"\nSkills de {ORIGEM_SKILLS} espelhadas para {COPIA_SKILLS}")
    espelhar_e_relatar(raiz)
    return 0


ORIGEM_SKILLS = ".agents/skills"
COPIA_SKILLS = ".claude/skills"


def espelhar_skills(raiz: Path) -> list:
    """Copia as skills de .agents/skills para .claude/skills.

    A fonte é .agents/skills — o caminho que quase todo agente lê. O Claude
    Code lê só o seu próprio diretório, então recebe uma cópia. A cópia é
    derivada: sobrescrita quando difere da fonte, e o que sumiu da fonte sai
    dela também — senão o Claude seguiria lendo conteúdo já apagado.
    """
    origem, destino = raiz / ORIGEM_SKILLS, raiz / COPIA_SKILLS
    mexidos = []
    if not origem.is_dir():
        return mexidos
    for arquivo in sorted(origem.rglob("*")):
        if arquivo.is_dir() or arquivo.name == ".gitkeep":
            continue
        alvo = destino / arquivo.relative_to(origem)
        dados = arquivo.read_bytes()
        if alvo.exists() and alvo.read_bytes() == dados:
            continue
        alvo.parent.mkdir(parents=True, exist_ok=True)
        alvo.write_bytes(dados)
        mexidos.append(("copiado", alvo.relative_to(raiz).as_posix()))
    # A limpeza vale só dentro de skill que a fonte ainda tem. Skill inteira
    # que só existe na cópia foi escrita à mão no lugar errado — o verificador
    # manda mover, e apagar aqui destruiria a única versão.
    if destino.is_dir():
        for arquivo in sorted(destino.rglob("*")):
            if arquivo.is_dir() or arquivo.name == ".gitkeep":
                continue
            rel = arquivo.relative_to(destino)
            if (origem / rel.parts[0]).is_dir() and not (origem / rel).exists():
                arquivo.unlink()
                mexidos.append(("removido", (destino / rel).relative_to(raiz).as_posix()))
    return mexidos


def espelhar_e_relatar(raiz: Path) -> None:
    mexidos = espelhar_skills(raiz)
    for acao, caminho in mexidos:
        print(f"  {acao}: {caminho}")
    if not mexidos:
        print("  nada a espelhar (as cópias já estavam em dia)")


def garantir_linhas(destino: Path, linhas, rotulo: str,
                    motivo: str = MOTIVO_IGNORAR) -> None:
    """Acrescenta as linhas que faltam. Não reescreve o que já está lá.

    O `escrever` mantém arquivo existente — o que aqui seria perigoso: um
    `.gitignore` que já existe deixaria `.credenciais/` de fora e o segredo
    entraria no git na primeira adição em massa.
    """
    texto = destino.read_text(encoding="utf-8") if destino.exists() else ""
    faltando = [l for l in linhas if l not in texto.splitlines()]
    if not faltando:
        print(f"  em dia:  {rotulo}")
        return

    novo = texto
    if novo and not novo.endswith("\n"):
        novo += "\n"
    if novo:
        novo += "\n"
    # O comentário entra uma vez só: rodar de novo com uma pasta nova não pode
    # deixar o arquivo cheio da mesma linha repetida.
    if motivo not in texto:
        novo += motivo + "\n"
    novo += "\n".join(faltando) + "\n"
    destino.write_text(novo, encoding="utf-8", newline="\n")
    print(f"  ajustado: {rotulo} (+{', '.join(faltando)})")


def garantir_gitignore_do_esqueleto(raiz: Path) -> None:
    """Migra as linhas antigas do esqueleto para a forma que preserva a pasta.

    `projetos/` escondia qualquer pasta homônima em qualquer profundidade;
    `/projetos/` escondia a pasta inteira — e pasta ignorada não chega no
    clone. A forma atual ignora só o conteúdo, e as exceções do LEIAME
    seguram a estrutura no git.
    """
    destino = raiz / ".gitignore"
    if not destino.exists():
        return
    trocas = {}
    for pasta in ("projetos", ".credenciais", "recursos"):
        trocas[f"{pasta}/"] = f"/{pasta}/*"
        trocas[f"/{pasta}/"] = f"/{pasta}/*"
    linhas = destino.read_text(encoding="utf-8").splitlines()
    trocadas = []
    for i, linha in enumerate(linhas):
        if linha in trocas:
            linhas[i] = trocas[linha]
            trocadas.append(linhas[i])
    if trocadas:
        destino.write_text("\n".join(linhas) + "\n", encoding="utf-8", newline="\n")
        print(f"  ajustado: .gitignore (esqueleto preserva a pasta: {', '.join(trocadas)})")
    # Quem tem o esqueleto precisa também das exceções — sem elas, os LEIAMEs
    # seguem ignorados e a estrutura continua não chegando no clone.
    if any(l in trocas.values() for l in linhas):
        garantir_linhas(destino, IGNORAR, ".gitignore (exceções do esqueleto)")


def garantir_devin(raiz: Path) -> None:
    """Desliga a ponte para a .claude e garante as negações próprias do Devin.

    Pela ponte, cada skill chegava em dobro (fonte + espelho) e permissão
    nenhuma vinha junto — o import não as traz. Config que já existe o
    `escrever` mantém; a emenda é feita aqui, preservando o resto.
    """
    destino = raiz / ".devin/config.json"
    if not destino.exists():
        return
    cfg = json.loads(destino.read_text(encoding="utf-8"))
    ponte = cfg.get("read_config_from", {}).get("claude")
    if ponte is False and "permissions" in cfg:
        print("  em dia:  configuração do Devin (ponte desligada)")
        return
    cfg.setdefault("read_config_from", {})["claude"] = False
    cfg.setdefault("permissions", json.loads("{" + PERMISSOES + "}")["permissions"])
    destino.write_text(json.dumps(cfg, indent=2, ensure_ascii=False) + "\n",
                       encoding="utf-8", newline="\n")
    print("  ajustado: .devin/config.json (ponte desligada, negações próprias)")


def garantir_espelho_no_git(raiz: Path) -> None:
    """Tira a linha skills/ do .claude/.gitignore de quem já tem a camada.

    A cópia era mantida fora do git; sessão na nuvem só enxerga o commitado,
    então a regra mudou — e arquivo existente o `escrever` não corrige.
    """
    destino = raiz / ".claude/.gitignore"
    if not destino.exists():
        return
    linhas = destino.read_text(encoding="utf-8").splitlines()
    if "skills/" not in linhas:
        return
    novo = "\n".join(l for l in linhas if l != "skills/")
    destino.write_text(novo + ("\n" if novo else ""), encoding="utf-8", newline="\n")
    print("  ajustado: .claude/.gitignore (espelho de skills agora entra no git)")


def garantir_gancho(raiz: Path) -> None:
    """Liga o gancho da qualidade no settings.json sem mexer no resto.

    O `escrever` mantém arquivo que existe — e o settings.json quase sempre
    existe. Sem esta emenda, repositório que já recebeu a camada nunca
    ganharia o gancho.
    """
    destino = raiz / ".claude/settings.json"
