PONTEIRO_DAS_REGRAS = (
    "\n"
    "## As regras desta camada\n"
    "\n"
    "A lista numerada está em `conhecimento/regras-da-camada.md`. Leia antes de\n"
    "propor procedimento, de mexer em branch de longa duração e de tocar em\n"
    "configuração de esteira.\n"
)


def garantir_ponteiro_das_regras(raiz: Path) -> None:
    """Acrescenta ao AGENTS.md o endereço da lista numerada, se ele não o tiver.

    É a segunda porta, e ela existe porque a primeira não passa. O
    `--atualizar` reescreve as páginas do guia e **nunca** o `AGENTS.md`, de
    propósito: a primeira regra de um repositório público é o oposto da de um
    privado. A consequência foi medida num repositório real — a lista de
    regras chegava atualizada ao disco a cada atualização, e nenhuma sessão a
    lia, porque nada mandava ler. Regra nova só valia para quem montasse do
    zero depois dela.

    Daí o formato. O que se acrescenta é o ENDEREÇO, nunca as regras: a lista
    tem uma casa só, e uma cópia dela envelheceria torta justamente do lado
    que a atualização não reescreve. Acrescenta uma vez e para; nunca
    reescreve, nunca reordena, nunca toca no que é do repositório.
    """
    destino = raiz / "AGENTS.md"
    if not destino.exists():
        print("  pulado: AGENTS.md não existe aqui")
        return
    texto = destino.read_text(encoding="utf-8")
    if "regras-da-camada" in texto:
        print("  em dia:  o AGENTS.md aponta a lista de regras")
        return
    if not texto.endswith("\n"):
        texto += "\n"
    destino.write_text(texto + PONTEIRO_DAS_REGRAS, encoding="utf-8", newline="\n")
    print("  acrescentado: o endereço da lista de regras, no fim do AGENTS.md")


def garantir_veto(raiz: Path) -> None:
    """Liga o veto de branch protegida, sem mexer no resto do settings.json.

    Regra de texto erra dos dois lados: `git push origin +x` é forçado e
    `git push origin x` não é, e nenhum padrão separa os dois sem errar de um
    lado. O gancho lê o comando e separa. Como todo gancho, ele falha aberto —
    se não subir, a regra 12 continua valendo só como texto.
    """
    # Só liga o que existe: declaração apontando para arquivo que não está lá
    # falha em silêncio — o gancho não roda e nada avisa.
    if not (raiz / ".claude/hooks/vetar-branch-protegida.py").exists():
        print("  pulado:  veto de branch protegida (o gancho não está no disco)")
        return

    destino = raiz / ".claude/settings.json"
    cfg = json.loads(destino.read_text(encoding="utf-8")) if destino.exists() else {}
    antes = cfg.setdefault("hooks", {}).setdefault("PreToolUse", [])
    migrou = tirar_outras_formas(antes, "vetar-branch-protegida.py", COMANDO_VETO)
    if tem_comando(antes, COMANDO_VETO):
        if not migrou:
            print("  em dia:  veto de branch protegida no settings.json")
            return
    else:
        antes.append({"matcher": "Bash|PowerShell",
                      "hooks": [{"type": "command", "command": COMANDO_VETO}]})
    destino.parent.mkdir(parents=True, exist_ok=True)
    destino.write_text(json.dumps(cfg, indent=2, ensure_ascii=False) + "\n",
                       encoding="utf-8", newline="\n")
    print("  ligado:  veto de branch protegida no settings.json")


